    feedback=load('docs/training/FRESH_FEEDBACK_078.json')['records']
    accuracy=load('docs/training/WINNER_ACCURACY_078.json')
    solo=load('docs/training/OWNER_SPAM_CIRCLE_078.json')
    deployment=load('docs/training/PREALPHA_078_DEPLOYMENT.json')
